"""DANFSe v2.0 generated by the site from the AUTHORIZED NFS-e XML (returned by Sefin Nacional and checked by the site).

Layout reproduced from the official DANFSe v2.0 issued by the Portal Nacional (A4, coordinates in points measured on the
model provided by the office). There is no contributor API for the official PDF today (ADN restricted /danfse -> 404;
production docs -> 503; official ADN/Emissor Público manuals silent), so the page is rebuilt from the XML only: no value
is invented; missing information is printed as "-" exactly like the official document.
"""
from datetime import datetime
from decimal import Decimal, InvalidOperation
from pathlib import Path
import segno
from fpdf import FPDF
from lxml import etree

NS = {'n': 'http://www.sped.fazenda.gov.br/nfse'}
LOGO = Path(__file__).resolve().parent / 'data' / 'nfse-logo.png'
CONSULTA = {'1': 'https://www.nfse.gov.br/ConsultaPublica?tpc=1&chave=', '2': 'https://www.producaorestrita.nfse.gov.br/ConsultaPublica?tpc=1&chave='}
# Descriptions as in the official XSD (tiposSimples_v1.01).
OP_SIMP = {'1': 'Não Optante', '2': 'Optante - Microempreendedor Individual (MEI)', '3': 'Optante - Microempresa ou Empresa de Pequeno Porte (ME/EPP)'}
REG_AP = {'1': 'Regime de apuração dos tributos federais e municipal pelo Simples Nacional',
          '2': 'Regime de apuração dos tributos federais pelo SN e ISSQN por fora do SN conforme respectiva legislação municipal do tributo',
          '3': 'Regime de apuração dos tributos federais e municipal por fora do SN conforme respectivas legislações federal e municipal de cada tributo'}
TRIB_ISSQN = {'1': 'Operação Tributável', '2': 'Imunidade', '3': 'Exportação de Serviço', '4': 'Não Incidência'}
RET_ISSQN = {'1': 'Não Retido', '2': 'Retido pelo Tomador', '3': 'Retido pelo Intermediário'}
EMITENTE = {'1': 'Prestador', '2': 'Tomador', '3': 'Intermediário'}
FINALIDADE = {'0': 'NFS-e regular'}

# Geometry of the model (points). Four columns; text starts 3.4 pt after each column line.
COL = [11.9, 156.5, 301.0, 445.6]
COL_W = 141.0
LEFT, RIGHT = 8.5, 586.8
GRAY = (242, 242, 242)
ROW = 19.05


def _latin1(text) -> str:
    table = str.maketrans({'—': '-', '–': '-', '“': '"', '”': '"', '‘': "'", '’': "'", '…': '...', '•': '-', ' ': ' '})
    return str(text if text not in (None, '') else '-').translate(table).encode('latin-1', 'replace').decode('latin-1')


def _doc(value) -> str:
    d = ''.join(ch for ch in str(value or '') if ch.isdigit())
    if len(d) == 14:
        return f'{d[:2]}.{d[2:5]}.{d[5:8]}/{d[8:12]}-{d[12:]}'
    if len(d) == 11:
        return f'{d[:3]}.{d[3:6]}.{d[6:9]}-{d[9:]}'
    return d or '-'


def _money(value) -> str:
    try:
        n = Decimal(str(value))
    except (InvalidOperation, ValueError):
        return '-'
    return 'R$ ' + f'{n:,.2f}'.replace(',', 'X').replace('.', ',').replace('X', '.')


def _pct(value) -> str:
    return (str(value).replace('.', ',') + '%') if value else '-'


def _date(value, with_time=True) -> str:
    try:
        dt = datetime.fromisoformat(str(value))
    except ValueError:
        return value or '-'
    return dt.strftime('%d/%m/%Y %H:%M:%S' if with_time else '%d/%m/%Y')


def _ibge(code) -> str:
    return f'{code[:2]}.{code[2:]}' if len(code or '') == 7 else (code or '-')


def _cep(cep) -> str:
    return f'{cep[:2]}.{cep[2:5]}-{cep[5:]}' if len(cep or '') == 8 else (cep or '-')


def _ctrib(code) -> str:
    return f'{code[:2]}.{code[2:4]}.{code[4:]}' if len(code or '') == 6 else (code or '-')


def _nbs(code) -> str:
    return f'{code[0]}.{code[1:5]}.{code[5:7]}.{code[7:]}' if len(code or '') == 9 else (code or '-')


class _Doc:
    def __init__(self, xml: str):
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        self.root = etree.fromstring(xml.encode('utf-8'), parser)
        self.inf = self.root.find('n:infNFSe', NS)
        self.dps = self.root.find('n:infNFSe/n:DPS/n:infDPS', NS)
        if self.inf is None or self.dps is None:
            raise ValueError('XML da NFS-e sem infNFSe/infDPS.')

    @staticmethod
    def t(node, path) -> str:
        return (node.findtext(path, namespaces=NS) or '').strip() if node is not None else ''


def build_danfse(nfse_xml: str) -> bytes:
    d = _Doc(nfse_xml)
    inf, dps, t = d.inf, d.dps, d.t
    key = (inf.get('Id') or '')[3:]
    tp_amb = t(dps, 'n:tpAmb')
    emit = inf.find('n:emit', NS)
    emit_end = emit.find('n:enderNac', NS) if emit is not None else None
    uf = t(emit_end, 'n:UF')
    c_loc_emi = t(dps, 'n:cLocEmi')
    prest = dps.find('n:prest', NS)
    toma = dps.find('n:toma', NS)
    toma_end = toma.find('n:end', NS) if toma is not None else None
    serv = dps.find('n:serv', NS)
    vals = dps.find('n:valores', NS)
    trib_mun = vals.find('n:trib/n:tribMun', NS) if vals is not None else None
    trib_fed = vals.find('n:trib/n:tribFed', NS) if vals is not None else None
    tot = vals.find('n:trib/n:totTrib', NS) if vals is not None else None
    v_nfse = inf.find('n:valores', NS)

    def city(code, name_hint=''):
        # Names come from the NFS-e itself; for another municipality without a name in the XML, show the IBGE code.
        if name_hint:
            return name_hint
        if code and code == c_loc_emi:
            return f"{t(inf, 'n:xLocEmi')} / {uf}" if uf else t(inf, 'n:xLocEmi')
        return f'IBGE {code}' if code else '-'

    pdf = FPDF(unit='pt', format=(595, 842))
    pdf.set_auto_page_break(False)
    pdf.add_page()
    pdf.set_draw_color(0, 0, 0)

    def text(x, base, value, size=7, bold=False, color=(0, 0, 0), width=COL_W):
        pdf.set_font('Helvetica', 'B' if bold else '', size)
        pdf.set_text_color(*color)
        s = _latin1(value)
        if width and pdf.get_string_width(s) > width:  # truncate like the official document ("...")
            while s and pdf.get_string_width(s + '...') > width:
                s = s[:-1]
            s += '...'
        pdf.text(x, base, s)

    def hline(y, x0=LEFT, x1=RIGHT, w=0.5):
        pdf.set_line_width(w)
        pdf.line(x0, y, x1, y)

    def gray(x0, y0, x1, y1):
        pdf.set_fill_color(*GRAY)
        pdf.rect(x0, y0, x1 - x0, y1 - y0, style='F')

    def field(col, top, label, value, label_size=6, label_bold=True, span=1):
        width = COL_W * span + 3.6 * (span - 1)
        text(COL[col], top + 5.9, label, size=label_size, bold=label_bold, width=width)
        text(COL[col], top + 13.6, value, width=width)

    def section(line_y, heading, rows):
        """rows: list of lists of (col, label, value[, span]); the first row starts beside the gray heading cell."""
        hline(line_y)
        gray(LEFT, line_y + 0.2, 153.1, line_y + 19.4)
        text(COL[0], line_y + 6.8, heading, size=7, bold=True)
        for k, row in enumerate(rows):
            for item in row:
                col, label, value = item[:3]
                field(col, line_y + ROW * k, label, value, span=item[3] if len(item) > 3 else 1)
        return line_y + ROW * len(rows)

    # Outer border
    pdf.set_line_width(1.0)
    pdf.rect(5, 5, 585, 832)

    # Header band
    gray(LEFT, 5.7, RIGHT, 39.7)
    hline(39.9)
    if LOGO.is_file():
        pdf.image(str(LOGO), x=11.9, y=10.3, w=115.7, h=22.9)
    for base, value, color in [(15.6, 'DANFSe v2.0', (0, 0, 0)), (25.9, 'Documento Auxiliar da NFS-e', (0, 0, 0))] + \
            ([(36.3, 'NFS-e SEM VALIDADE JURÍDICA', (255, 0, 0))] if tp_amb == '2' else []):
        pdf.set_font('Helvetica', 'B', 9)
        pdf.set_text_color(*color)
        s = _latin1(value)
        pdf.text(297.6 - pdf.get_string_width(s) / 2, base, s)
    text(445.6, 18.7, f"Município: {t(inf, 'n:xLocEmi')}" + (f' - {uf}' if uf else ''), size=8)
    text(445.6, 25.9, f"Ambiente Gerador: {t(inf, 'n:ambGer') or '-'}", size=6)
    text(445.6, 32.7, f'Tipo de Ambiente: {tp_amb or "-"}', size=6)

    # Identification block + QR code
    text(COL[0], 51.0, 'CHAVE DE ACESSO DA NFS-e', bold=True)
    text(COL[0], 58.9, key, width=300)
    # QR code drawn as vector squares (crisp at any zoom; no raster format quirks).
    qr = segno.make(CONSULTA.get(tp_amb, CONSULTA['1']) + key, error='m')
    matrix = [list(r) for r in qr.matrix]
    module = 45.0 / len(matrix)
    pdf.set_fill_color(255, 255, 255)
    pdf.rect(492.0 - module, 44.8 - module, 45 + 2 * module, 45 + 2 * module, style='F')  # quiet zone over the gray band
    pdf.set_fill_color(0, 0, 0)
    for r, cells in enumerate(matrix):
        c = 0
        while c < len(cells):
            if cells[c]:
                start = c
                while c < len(cells) and cells[c]:
                    c += 1
                pdf.rect(492.0 + start * module, 44.8 + r * module, (c - start) * module + 0.05, module + 0.05, style='F')
            else:
                c += 1
    for base, line in [(97.4, 'A autenticidade desta NFS-e pode ser verificada'), (104.2, 'pela leitura deste código QR ou pela consulta da'),
                       (111.0, 'chave de acesso no portal nacional da NFS-e')]:
        text(445.6, base, line, size=6)
    for top, cells in [(64.9, [('NÚMERO DA NFS-e', t(inf, 'n:nNFSe')), ('COMPETÊNCIA DA NFS-e', _date(t(dps, 'n:dCompet'), False)),
                               ('DATA E HORA DA EMISSÃO DA NFS-e', _date(t(inf, 'n:dhProc')))]),
                       (85.1, [('NÚMERO DA DPS', t(dps, 'n:nDPS')), ('SÉRIE DA DPS', t(dps, 'n:serie')),
                               ('DATA E HORA DA EMISSÃO DA DPS', _date(t(dps, 'n:dhEmi')))])]:
        for col, (label, value) in enumerate(cells):
            text(COL[col], top + 6.3, label, size=7, bold=True)
            text(COL[col], top + 14.3, value)
    gray(LEFT, 105.1, 153.1, 125.3)
    situacao = 'NFS-e Gerada' if t(inf, 'n:cStat') == '100' else (t(inf, 'n:cStat') or '-')
    for col, (label, value) in enumerate([('EMITENTE DA NFS-e', EMITENTE.get(t(dps, 'n:tpEmit'), '-')), ('SITUAÇÃO DA NFS-e', situacao),
                                          ('FINALIDADE', FINALIDADE.get(t(dps, 'n:finNFSe'), t(dps, 'n:finNFSe') or '-'))]):
        text(COL[col], 111.7, label, size=7, bold=True)
        text(COL[col], 119.6, value)

    # Prestador
    end_line = ', '.join(p for p in [t(emit_end, 'n:xLgr'), t(emit_end, 'n:nro'), t(emit_end, 'n:xCpl'), t(emit_end, 'n:xBairro')] if p)
    y = section(125.6, 'PRESTADOR / FORNECEDOR', [
        [(1, 'CNPJ / CPF / NIF', _doc(t(emit, 'n:CNPJ') or t(emit, 'n:CPF') or t(prest, 'n:NIF'))),
         (2, 'Indicador Municipal (Inscrição)', t(prest, 'n:IM')), (3, 'Telefone', t(prest, 'n:fone'))],
        [(0, 'Nome / Nome Empresarial', t(emit, 'n:xNome') or t(prest, 'n:xNome'), 2),
         (2, 'Município / Sigla UF', city(t(emit_end, 'n:cMun'))), (3, 'Código IBGE / CEP', f"{_ibge(t(emit_end, 'n:cMun'))} / {_cep(t(emit_end, 'n:CEP'))}" if emit_end is not None else '-')],
        [(0, 'Endereço', end_line, 2), (2, 'E-mail', t(prest, 'n:email'))],
        [(0, 'Simples Nacional na Data de Competência', OP_SIMP.get(t(prest, 'n:regTrib/n:opSimpNac'), '-')),
         (1, 'Regime de Apuração Tributária pelo SN', REG_AP.get(t(prest, 'n:regTrib/n:regApTribSN'), '-'), 3)],
    ])

    # Tomador
    nac = toma_end.find('n:endNac', NS) if toma_end is not None else None
    toma_line = ', '.join(p for p in [t(toma_end, 'n:xLgr'), t(toma_end, 'n:nro'), t(toma_end, 'n:xCpl'), t(toma_end, 'n:xBairro')] if p)
    y = section(202.4, 'TOMADOR / ADQUIRENTE', [
        [(1, 'CNPJ / CPF / NIF', _doc(t(toma, 'n:CNPJ') or t(toma, 'n:CPF') or t(toma, 'n:NIF'))),
         (2, 'Indicador Municipal (Inscrição)', t(toma, 'n:IM')), (3, 'Telefone', t(toma, 'n:fone'))],
        [(0, 'Nome / Nome Empresarial', t(toma, 'n:xNome'), 2), (2, 'Município / Sigla UF', city(t(nac, 'n:cMun')) if nac is not None else '-'),
         (3, 'Código IBGE / CEP', f"{_ibge(t(nac, 'n:cMun'))} / {_cep(t(nac, 'n:CEP'))}" if nac is not None else '-')],
        [(0, 'Endereço', toma_line, 2), (2, 'E-mail', t(toma, 'n:email'))],
    ])

    # Destinatário / intermediário
    hline(260.1)
    hline(268.5)
    dest = 'DESTINATÁRIO DA OPERAÇÃO NÃO IDENTIFICADO NA NFS-e' if dps.find('n:IBSCBS/n:dest', NS) is None else 'DESTINATÁRIO DA OPERAÇÃO IDENTIFICADO NA NFS-e'
    interm = 'INTERMEDIÁRIO DA OPERAÇÃO NÃO IDENTIFICADO NA NFS-e' if dps.find('n:interm', NS) is None else 'INTERMEDIÁRIO DA OPERAÇÃO IDENTIFICADO NA NFS-e'
    for base, value in [(266.8, dest), (275.2, interm)]:
        pdf.set_font('Helvetica', '', 7)
        pdf.set_text_color(0, 0, 0)
        s = _latin1(value)
        pdf.text(297.6 - pdf.get_string_width(s) / 2, base, s)

    # Serviço prestado (description may wrap: following sections move down)
    line_y = 276.9
    hline(line_y)
    gray(LEFT, line_y + 0.2, 153.1, line_y + 19.4)
    text(COL[0], line_y + 6.8, 'SERVIÇO PRESTADO', size=7, bold=True)
    c_loc_prest = t(serv, 'n:locPrest/n:cLocPrestacao')
    loc_prest = t(inf, 'n:xLocPrestacao') or (f'IBGE {c_loc_prest}' if c_loc_prest else '-')
    field(1, line_y, 'Código de Tributação Nacional/Municipal', f"{_ctrib(t(serv, 'n:cServ/n:cTribNac'))} / {t(serv, 'n:cServ/n:cTribMun') or '-'}")
    field(2, line_y, 'Código da NBS', _nbs(t(serv, 'n:cServ/n:cNBS')))
    field(3, line_y, 'Local da Prestação / Sigla UF / País', f"{loc_prest} / {uf if c_loc_prest == t(emit_end, 'n:cMun') and uf else '-'} / {t(serv, 'n:locPrest/n:cPaisPrestacao') or '-'}")
    text(COL[0], line_y + 25.8, t(inf, 'n:xTribNac'), width=RIGHT - COL[0] - 3)
    text(COL[0], line_y + 37.2, 'Descrição do Serviço', size=6, bold=True)
    pdf.set_font('Helvetica', '', 7)
    desc = pdf.multi_cell(RIGHT - COL[0] - 3, 7.7, _latin1(t(serv, 'n:cServ/n:xDescServ')), dry_run=True, output='LINES')
    for i, line in enumerate(desc[:12]):
        pdf.text(COL[0], line_y + 44.9 + 7.7 * i, line)
    shift = 7.7 * (max(1, min(len(desc), 12)) - 1)
    base = line_y + 50.9 + shift  # model: next section line at 327.8

    # Tributação municipal
    hline(base)
    gray(LEFT, base + 0.2, 153.1, base + 19.4)
    text(COL[0], base + 6.8, 'TRIBUTAÇÃO MUNICIPAL (ISSQN)', size=7, bold=True)
    c_incid = t(inf, 'n:cLocIncid')
    field(1, base, 'Tipo de Tributação do ISSQN', TRIB_ISSQN.get(t(trib_mun, 'n:tribISSQN'), '-'))
    field(2, base, 'Município / Sigla UF / País de Incidência do ISSQN',
          f"{t(inf, 'n:xLocIncid') or '-'} / {uf if c_incid and c_incid == t(emit_end, 'n:cMun') and uf else '-'} / -", span=2)
    for col, label, value in [(0, 'BC ISSQN', _money(t(v_nfse, 'n:vBC')) if t(v_nfse, 'n:vBC') else '-'),
                              (1, 'Alíquota Aplicada', _pct(t(v_nfse, 'n:pAliqAplic'))),
                              (2, 'Retenção do ISSQN', RET_ISSQN.get(t(trib_mun, 'n:tpRetISSQN'), '-')),
                              (3, 'ISSQN Apurado', _money(t(v_nfse, 'n:vISSQN')) if t(v_nfse, 'n:vISSQN') else '-')]:
        field(col, base + ROW, label, value)

    # Tributação federal
    fed = lambda path: _money(t(trib_fed, path)) if t(trib_fed, path) else '-'
    base = section(base + 38.6, 'TRIBUTAÇÃO FEDERAL (EXCETO CBS)', [
        [(1, 'IRRF', fed('n:vRetIRRF')), (2, 'Contribuição Previdenciária - Retida', fed('n:vRetCP')),
         (3, 'Contribuições Sociais - Retidas', fed('n:vRetCSLL'))],
        [(0, 'PIS - Débito Apuração Própria', fed('n:piscofins/n:vPis')), (1, 'COFINS - Débito Apuração Própria', fed('n:piscofins/n:vCofins')),
         (2, 'Descrição Contrib. Sociais - Retidas', '-')],
    ])

    # Tributação IBS/CBS (the office does not inform IBS/CBS yet: dashes, as in the official model)
    ibs = dps.find('n:IBSCBS', NS)
    cst = t(ibs, 'n:valores/n:trib/n:CST')
    hline(base)
    gray(LEFT, base + 0.2, 153.1, base + 19.4)
    text(COL[0], base + 6.8, 'TRIBUTAÇÃO IBS/CBS', size=7, bold=True)
    field(1, base, 'CST / cClassTrib', f"{cst or '-'} / {t(ibs, 'n:valores/n:trib/n:cClassTrib') or '-'}")
    field(2, base, 'Indicador de Operação / Código IBGE Incidência / Município Incidência / Sigla UF', f"{t(ibs, 'n:cIndOp') or '-'} / - / - / -", span=2)
    for k, row in enumerate([
        [(0, 'Exclusões e Reduções da Base de Cálculo', 'R$ 0,00'), (1, 'Base de Cálculo Após Exclusões e Reduções', '-'),
         (2, 'Red. Alíquota IBS / Red. Alíquota CBS', '- / - / -'), (3, 'Alíquota - IBS UF / IBS Mun', '- / -')],
        [(0, 'Alíq. Efetiva Municipal - IBS', '-'), (1, 'Valor Apurado Municipal - IBS', '-'), (2, 'Alíq. Efetiva Estadual - IBS', '-'),
         (3, 'Valor Apurado Estadual - IBS', '-')],
        [(0, 'Valor Total Apurado - IBS', '-'), (1, 'Alíquota - CBS', '-'), (2, 'Alíquota Efetiva - CBS', '-'), (3, 'Valor Total Apurado - CBS', '-')],
    ], start=1):
        for col, label, value in row:
            field(col, base + ROW * k, label, value)
    base += ROW * 4 + 0.6

    # Valor total
    desc_inc = t(vals, 'n:vDescCondIncond/n:vDescIncond')
    desc_cond = t(vals, 'n:vDescCondIncond/n:vDescCond')
    total_ret = t(v_nfse, 'n:vTotalRet')
    gray(442.2, base + ROW, RIGHT, base + ROW * 2 + 0.2)
    base = section(base, 'VALOR TOTAL DA NFS-e', [
        [(1, 'VALOR DA OPERAÇÃO / SERVIÇO', _money(t(vals, 'n:vServPrest/n:vServ'))), (2, 'Desconto Incondicionado', _money(desc_inc) if desc_inc else '-'),
         (3, 'Desconto Condicionado', _money(desc_cond) if desc_cond else '-')],
        [(0, 'Total das Retenções (ISSQN / Federais)', _money(total_ret) if total_ret else '-'), (1, 'VALOR LÍQUIDO DA NFS-e', _money(t(v_nfse, 'n:vLiq'))),
         (2, 'Total do IBS/CBS', 'R$ 0,00'), (3, 'VALOR LÍQUIDO DA NFS-e + IBS/CBS', 'R$ 0,00')],
    ])

    # Informações complementares
    hline(base + 0.6)
    text(COL[0], base + 7.4, 'INFORMAÇÕES COMPLEMENTARES', size=7, bold=True)
    p_fed, p_est, p_mun = (t(tot, f'n:pTotTrib/n:pTotTrib{s}') for s in ('Fed', 'Est', 'Mun'))
    lines = []
    obs = t(serv, 'n:infoCompl/n:xInfComp')
    if obs:
        pdf.set_font('Helvetica', '', 7)
        lines += pdf.multi_cell(RIGHT - COL[0] - 3, 7.7, _latin1(obs), dry_run=True, output='LINES')
    lines.append(f"Totais aproximados dos Tributos cfe. Lei n° 12.741/2012: Federais: {_pct(p_fed)}; Estaduais: {_pct(p_est)}; Municipais: {_pct(p_mun)};")
    for i, line in enumerate(lines[:20]):
        text(COL[0], base + 27.5 + 9.0 * i, line, width=RIGHT - COL[0] - 3)

    # Footer receipt box
    pdf.set_line_width(1.0)
    for x0, x1 in [(9.0, 153.6), (153.6, 298.1), (298.1, 587.3)]:
        pdf.rect(x0, 795.8, x1 - x0, 20.1)
    text(12.9, 801.9, 'DATA CIENTIFICAÇÃO:', size=6, bold=True)
    text(157.5, 801.9, 'IDENTIFICAÇÃO E ASSINATURA', size=6, bold=True)
    text(302.0, 801.9, 'N° NFS-e / CHAVE NFS-e', size=6, bold=True)
    text(302.0, 809.7, f"{t(inf, 'n:nNFSe')} / {key}", width=280)

    return bytes(pdf.output())
